def xml(self, attribs = None,elements = None, skipchildren = False):
        """Serialises the FoLiA element to XML, by returning an XML Element (in lxml.etree) for this element and all its children. For string output, consider the xmlstring() method instead."""
        #if not attribs:
        #    attribs = self.attribs
        if elements:
            if type(elements) != list:
                elements = [elements]
        else:
            elements = []

        if self.attribs:
            if type(self.attribs) != dict:
                raise TypeError('attribs should be a dict')
            attribs = self.attribs
        else:
            attribs = {}

        if self.text and not skipchildren:
            attribs['text'] = self.text

        xml = etree.Element(self.name,attribs=attribs)
        if self.children and not skipchildren:
            for child in self.children:
                xml.append(child.xml())
        if elements:
            for child in elements:
                xml.append(child.xml())
        return xml

